#' Fit a `{{model}}`
#'
#' `{{model}}()` fits a Poisson regression model, using [stats::glm.fit()]
#' as the engine so that all of R's mature GLM fitting machinery is reused.
#'
#' If the formula interface is used, any `offset()` terms are extracted from
#' the `extras` generated by [hardhat::mold()] and are included in the linear
#' predictor, both at fit time and at prediction time. Multiple offsets have
#' already been summed together by `mold()`. Offsets are never included in
#' the predictor matrix, so they can't be learned as model coefficients.
#'
#' @param x Depending on the context:
#'
#'   * A __data frame__ of predictors.
#'   * A __matrix__ of predictors.
#'   * A __recipe__ specifying a set of preprocessing steps
#'     created from [recipes::recipe()].
#'
#' @param y When `x` is a __data frame__ or __matrix__, `y` is the outcome
#' specified as:
#'
#'   * A __data frame__ with 1 numeric column.
#'   * A __matrix__ with 1 numeric column.
#'   * A numeric __vector__.
#'
#' @param data When a __recipe__ or __formula__ is used, `data` is specified as:
#'
#'   * A __data frame__ containing both the predictors and the outcome.
#'
#' @param formula A formula specifying the outcome terms on the left-hand side,
#' and the predictor terms on the right-hand side.
#'
#' @param ... Not currently used, but required for extensibility.
#'
#' @return
#'
#' A `{{model}}` object.
#'
#' @examples
#' predictors <- mtcars[, -4]
#' outcome <- mtcars[, 4]
#'
#' # XY interface
#' mod <- {{model}}(predictors, outcome)
#'
#' # Formula interface
#' mod2 <- {{model}}(hp ~ ., mtcars)
#'
#' # Formula interface with an offset
#' mod3 <- {{model}}(hp ~ cyl + offset(log(disp)), mtcars)
#'
#' # Recipes interface
#' library(recipes)
#' rec <- recipe(hp ~ ., mtcars)
#' rec <- step_log(rec, disp)
#' mod4 <- {{model}}(rec, mtcars)
#'
#' @export
{{model}} <- function(x, ...) {
  UseMethod("{{model}}")
}

#' @export
#' @rdname {{model}}
{{model}}.default <- function(x, ...) {
  stop("`{{model}}()` is not defined for a '", class(x)[1], "'.", call. = FALSE)
}

# XY method - data frame

#' @export
#' @rdname {{model}}
{{model}}.data.frame <- function(x, y, ...) {
  processed <- hardhat::mold(x, y)
  {{model}}_bridge(processed, ...)
}

# XY method - matrix

#' @export
#' @rdname {{model}}
{{model}}.matrix <- function(x, y, ...) {
  processed <- hardhat::mold(x, y)
  {{model}}_bridge(processed, ...)
}

# Formula method

#' @export
#' @rdname {{model}}
{{model}}.formula <- function(formula, data, ...) {
  processed <- hardhat::mold(formula, data)
  {{model}}_bridge(processed, ...)
}

# Recipe method

#' @export
#' @rdname {{model}}
{{model}}.recipe <- function(x, data, ...) {
  processed <- hardhat::mold(x, data)
  {{model}}_bridge(processed, ...)
}

# ------------------------------------------------------------------------------
# Bridge

{{model}}_bridge <- function(processed, ...) {
  predictors <- as.matrix(processed$predictors)
  outcome <- processed$outcomes[[1]]

  # `mold()` moves any `offset()` terms from the formula into `extras`, already
  # summed into a single `.offset` vector. They never appear in `predictors`,
  # so they can't be learned as coefficients.
  offset <- extract_{{model}}_offset(processed$extras)

  fit <- {{model}}_impl(predictors, outcome, offset)

  new_{{model}}(
    coefs = fit$coefs,
    blueprint = processed$blueprint
  )
}

# ------------------------------------------------------------------------------
# Implementation

{{model}}_impl <- function(predictors, outcome, offset) {
  fit <- stats::glm.fit(
    x = predictors,
    y = outcome,
    family = stats::poisson(),
    offset = offset
  )

  list(coefs = fit$coefficients)
}

# ------------------------------------------------------------------------------
# Offset

# Shared by the fit and predict bridges. `extras` comes from a call to
# `hardhat::mold()` or `hardhat::forge()`. Returns `NULL` when no offset was
# supplied, and errors on missing or non-finite exposures.
extract_{{model}}_offset <- function(extras, call = rlang::caller_env()) {
  offset <- extras$offset$.offset

  if (is.null(offset)) {
    return(NULL)
  }

  if (!is.numeric(offset)) {
    rlang::abort("`offset` must be a numeric vector.", call = call)
  }

  if (any(!is.finite(offset))) {
    rlang::abort(
      "`offset` can't contain missing or non-finite values.",
      call = call
    )
  }

  offset
}
